<?php require_once __DIR__.'/../includes/bootstrap.php';require_login();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT * FROM documents WHERE id=?');$q->execute([$id]);$d=$q->fetch();if(!$d) {http_response_code(404);exit('Not found');}$u=current_user();$allowed=has_role('Super Admin','College Admin','IT/System Administrator') || (int)$d['owner_user_id']===(int)$u['id'] || can('documents.manage');if(!$allowed){http_response_code(403);exit('Forbidden');}$path=__DIR__.'/../storage/private/'.basename($d['file_path']);if(!is_file($path)){http_response_code(404);exit('File missing');}header('Content-Type: '.($d['mime_type']?:'application/octet-stream'));header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.preg_replace('/[^A-Za-z0-9._-]/','_',basename($d['file_path'])).'"');readfile($path);AuditService::log('DOWNLOAD','documents',$id,'Authorized document download');
